css.style.css:
/* Calculator function — styles */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: #0d1117; color: #c9d1d9;
  min-height: 100vh; display: flex; align-items: center; justify-content: center;
  padding: 12px;
}
.calc-app {
  width: 100%; max-width: 360px;
  background: #161b22; border: 1px solid #30363d; border-radius: 12px;
  overflow: hidden; box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}
.calc-header { padding: 16px; background: #161b22; border-bottom: 1px solid #30363d; }
.calc-header h1 { color: #58a6ff; font-size: 18px; margin-bottom: 4px; }
.calc-header .meta { color: #8b949e; font-size: 11px; }
.calc-header .meta code { background: #0d1117; padding: 1px 6px; border-radius: 3px; font-family: ui-monospace, monospace; color: #58a6ff; }
.calc-main { padding: 12px; }
.calc-display {
  background: #0d1117; border: 1px solid #30363d; border-radius: 8px;
  padding: 16px; margin-bottom: 12px; text-align: right; min-height: 80px;
  display: flex; flex-direction: column; justify-content: flex-end;
}
.calc-expression { font-size: 14px; color: #8b949e; min-height: 20px; word-break: break-all; }
.calc-result { font-size: 28px; color: #58a6ff; font-weight: 600; font-family: ui-monospace, monospace; }
.calc-keypad { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.key {
  background: #21262d; color: #c9d1d9; border: 1px solid #30363d;
  border-radius: 8px; padding: 14px 0; font-size: 16px; cursor: pointer;
  transition: all .12s; font-family: inherit;
}
.key:hover { background: #30363d; transform: translateY(-1px); }
.key:active { transform: translateY(0); }
.key.num { color: #e6edf3; }
.key.op { color: #bc8cff; }
.key.op.accent { color: #d29922; }
.key.clear { color: #f85149; }
.key.equals {
  background: #238636; color: #fff; border-color: #2ea043; grid-column: span 2;
}
.key.equals:hover { background: #2ea043; }
.calc-history { margin-top: 12px; color: #8b949e; font-size: 12px; }
.calc-history summary { cursor: pointer; padding: 8px; background: #0d1117; border-radius: 6px; }
.calc-history ul { list-style: none; padding: 8px; max-height: 200px; overflow-y: auto; }
.calc-history li { padding: 4px 8px; border-bottom: 1px solid #21262d; font-family: ui-monospace, monospace; }
.calc-footer { padding: 8px 16px; text-align: center; color: #6e7681; font-size: 10px; border-top: 1px solid #30363d; }

