css.style.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #0d1117; color: #c9d1d9; min-height: 100vh; padding: 12px; }
.notes-app { max-width: 720px; margin: 0 auto; }
.notes-header { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid #30363d; }
.notes-header h1 { color: #58a6ff; font-size: 22px; }
.btn-new { background: #238636; color: #fff; border: none; padding: 8px 14px; border-radius: 6px; cursor: pointer; font-size: 13px; }
.btn-new:hover { background: #2ea043; }
.notes-search { padding: 12px 0; }
.notes-search input { width: 100%; background: #161b22; color: #c9d1d9; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 13px; }
.notes-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }
.note-card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 12px; cursor: pointer; transition: all .12s; }
.note-card:hover { border-color: #58a6ff; transform: translateY(-2px); }
.note-card .title { color: #e6edf3; font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.note-card .body { color: #8b949e; font-size: 12px; line-height: 1.5; max-height: 60px; overflow: hidden; }
.note-card .date { color: #6e7681; font-size: 10px; margin-top: 6px; }
.notes-editor { position: fixed; inset: 0; background: #0d1117; padding: 16px; z-index: 100; display: flex; flex-direction: column; }
.editor-bar { display: flex; gap: 8px; padding-bottom: 12px; }
.editor-bar input { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 14px; }
.editor-bar button { background: #21262d; color: #c9d1d9; border: 1px solid #30363d; border-radius: 6px; padding: 8px 14px; cursor: pointer; font-size: 13px; }
.editor-bar .btn-save { background: #238636; color: #fff; }
.editor-bar .btn-delete { background: #da3633; color: #fff; }
.editor-bar .btn-close { background: transparent; font-size: 20px; padding: 4px 12px; }
#noteBody { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 12px; font-size: 14px; font-family: inherit; resize: none; min-height: 300px; }
.notes-footer { text-align: center; padding: 16px; color: #6e7681; font-size: 10px; }
.empty { color: #6e7681; text-align: center; padding: 40px; font-size: 13px; }

