css.style.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #0d1117; color: #c9d1d9; min-height: 100vh; padding: 16px; }
.todo-app { max-width: 540px; margin: 0 auto; }
header h1 { color: #58a6ff; font-size: 22px; }
header .meta { color: #8b949e; font-size: 11px; margin-top: 4px; }
header .meta code { background: #161b22; padding: 1px 6px; border-radius: 3px; color: #58a6ff; }
.add-form { display: flex; gap: 8px; margin: 16px 0; }
.add-form input { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 14px; }
.add-form button { background: #238636; color: #fff; border: none; padding: 0 20px; border-radius: 6px; cursor: pointer; font-size: 13px; }
.todo-stats { color: #8b949e; font-size: 12px; margin-bottom: 8px; }
.todo-list { list-style: none; }
.todo-list li { display: flex; align-items: center; gap: 10px; background: #161b22; border: 1px solid #30363d; border-radius: 6px; padding: 10px 12px; margin-bottom: 6px; }
.todo-list li.done { opacity: 0.5; }
.todo-list li.done .text { text-decoration: line-through; }
.todo-list input[type="checkbox"] { width: 18px; height: 18px; cursor: pointer; }
.todo-list .text { flex: 1; color: #e6edf3; font-size: 14px; }
.todo-list .date { color: #6e7681; font-size: 10px; }
.todo-list .del { background: transparent; color: #f85149; border: none; cursor: pointer; padding: 4px 8px; font-size: 16px; }
.todo-actions { display: flex; gap: 8px; margin-top: 16px; }
.todo-actions button { background: #21262d; color: #c9d1d9; border: 1px solid #30363d; border-radius: 6px; padding: 8px 14px; cursor: pointer; font-size: 12px; }
.todo-actions .danger { color: #f85149; }
footer { text-align: center; padding: 16px; color: #6e7681; font-size: 10px; }
.empty { color: #6e7681; text-align: center; padding: 40px; font-size: 13px; }

js.app.js:
/* Todo List function — front-end logic with localStorage */
(function () {
  'use strict';
  var STORAGE_KEY = 'bardom_todos';
  var todos = load();
  var form = document.getElementById('addForm');
  var input = document.getElementById('todoInput');
  var list = document.getElementById('todoList');
  var stats = document.getElementById('stats');

  function load() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'); }
    catch (e) { return []; }
  }
  function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); }
  function uuid() { return 't-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8); }
  function escapeHtml(s) {
    return String(s || '').replace(/[&<>"']/g, function (c) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }

  function render() {
    var done = todos.filter(function (t) { return t.done; }).length;
    var total = todos.length;
    stats.textContent = total ? (done + ' of ' + total + ' done') : 'No tasks yet';
    if (!todos.length) {
      list.innerHTML = '<div class="empty">No tasks. Add one above.</div>';
      return;
    }
    list.innerHTML = todos.map(function (t) {
      return '<li class="' + (t.done ? 'done' : '') + '">' +
             '<input type="checkbox" data-id="' + t.id + '" ' + (t.done ? 'checked' : '') + '>' +
             '<span class="text">' + escapeHtml(t.text) + '</span>' +
             '<span class="date">' + (t.completed_at || t.created_at) + '</span>' +
             '<button class="del" data-id="' + t.id + '">×</button>' +
             '</li>';
    }).join('');
    list.querySelectorAll('input[type=checkbox]').forEach(function (cb) {
      cb.addEventListener('change', function () { toggle(cb.dataset.id); });
    });
    list.querySelectorAll('.del').forEach(function (b) {
      b.addEventListener('click', function () { remove(b.dataset.id); });
    });
  }

  function add(text) {
    var now = new Date().toISOString();
    todos.unshift({ id: uuid(), text: text, done: false, created_at: now, completed_at: null });
    save(); render();
  }
  function toggle(id) {
    var t = todos.find(function (x) { return x.id === id; });
    if (t) {
      t.done = !t.done;
      t.completed_at = t.done ? new Date().toISOString() : null;
      save(); render();
    }
  }
  function remove(id) {
    todos = todos.filter(function (x) { return x.id !== id; });
    save(); render();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (text) { add(text); input.value = ''; }
  });
  document.getElementById('btnClearDone').addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.done; }); save(); render();
  });
  document.getElementById('btnClearAll').addEventListener('click', function () {
    if (confirm('Delete all tasks?')) { todos = []; save(); render(); }
  });
  render();
})();

