css.style.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: linear-gradient(180deg, #0d1117 0%, #161b22 100%); color: #c9d1d9; min-height: 100vh; padding: 16px; }
.weather-app { max-width: 540px; margin: 0 auto; }
header h1 { color: #58a6ff; font-size: 22px; }
header .meta { color: #8b949e; font-size: 11px; margin-top: 4px; }
header .meta code { background: #161b22; padding: 1px 6px; border-radius: 3px; color: #58a6ff; }
#searchForm { display: flex; gap: 8px; margin: 16px 0; }
#searchForm input { flex: 1; background: #161b22; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 14px; }
#searchForm button { background: #238636; color: #fff; border: none; padding: 0 18px; border-radius: 6px; cursor: pointer; font-size: 13px; }
.weather-card { background: #161b22; border: 1px solid #30363d; border-radius: 12px; padding: 24px; text-align: center; margin-bottom: 16px; }
.weather-card .city { color: #e6edf3; font-size: 24px; font-weight: 600; }
.weather-card .country { color: #8b949e; font-size: 12px; margin-bottom: 12px; }
.weather-card .temp { color: #58a6ff; font-size: 48px; font-weight: 700; font-family: ui-monospace, monospace; }
.weather-card .desc { color: #c9d1d9; font-size: 16px; margin-top: 4px; }
.weather-card .icon { font-size: 56px; margin: 12px 0; }
.weather-card .stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 16px; padding-top: 16px; border-top: 1px solid #30363d; }
.weather-card .stats div { text-align: center; }
.weather-card .stats span { display: block; color: #8b949e; font-size: 11px; margin-bottom: 4px; }
.weather-card .stats b { color: #e6edf3; font-size: 14px; }
.weather-error { background: rgba(248,81,73,0.1); border: 1px solid #f85149; border-radius: 8px; padding: 16px; color: #f85149; text-align: center; }
.weather-history { margin-top: 16px; }
.weather-history h3 { color: #58a6ff; font-size: 14px; margin-bottom: 8px; }
.weather-history ul { list-style: none; }
.weather-history li { background: #161b22; padding: 10px 12px; border-radius: 6px; border: 1px solid #30363d; margin-bottom: 4px; cursor: pointer; font-size: 13px; }
.weather-history li:hover { border-color: #58a6ff; }
footer { text-align: center; padding: 16px; color: #6e7681; font-size: 10px; }

js.app.js:
/* Weather function — front-end logic */
(function () {
  'use strict';
  var form = document.getElementById('searchForm');
  var input = document.getElementById('cityInput');
  var card = document.getElementById('weatherCard');
  var errorCard = document.getElementById('errorCard');
  var recent = JSON.parse(localStorage.getItem('bardom_weather_recent') || '[]');

  var ICONS = {
    0:'☀️', 1:'🌤️', 2:'⛅', 3:'☁️', 45:'🌫️', 48:'🌫️',
    51:'🌦️', 53:'🌦️', 55:'🌧️', 56:'🌧️', 57:'🌧️',
    61:'🌧️', 63:'🌧️', 65:'⛈️', 66:'🌧️', 67:'⛈️',
    71:'🌨️', 73:'🌨️', 75:'❄️', 77:'❄️',
    80:'🌦️', 81:'🌧️', 82:'⛈️', 85:'🌨️', 86:'❄️',
    95:'⛈️', 96:'⛈️', 99:'⛈️'
  };

  function saveRecent(city) {
    recent = recent.filter(function (c) { return c !== city; });
    recent.unshift(city);
    recent = recent.slice(0, 10);
    localStorage.setItem('bardom_weather_recent', JSON.stringify(recent));
    renderRecent();
  }
  function renderRecent() {
    var ul = document.getElementById('recentList');
    ul.innerHTML = recent.map(function (c) { return '<li>' + c + '</li>'; }).join('');
    ul.querySelectorAll('li').forEach(function (li) {
      li.addEventListener('click', function () { input.value = li.textContent; search(); });
    });
  }

  function search() {
    var city = input.value.trim();
    if (!city) return;
    card.hidden = true; errorCard.hidden = true;
    fetch('https://geocoding-api.open-meteo.com/v1/search?name=' + encodeURIComponent(city) + '&count=1&language=en&format=json')
      .then(function (r) { return r.json(); })
      .then(function (geo) {
        if (!geo.results || !geo.results.length) throw new Error('City not found');
        var g = geo.results[0];
        return fetch('https://api.open-meteo.com/v1/forecast?latitude=' + g.latitude + '&longitude=' + g.longitude + '&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m&timezone=auto')
          .then(function (r) { return r.json(); })
          .then(function (wx) { return { geo: g, wx: wx }; });
      })
      .then(function (data) {
        var cur = data.wx.current;
        var code = cur.weather_code;
        document.getElementById('city').textContent = data.geo.name;
        document.getElementById('country').textContent = data.geo.country || '';
        document.getElementById('temp').textContent = Math.round(cur.temperature_2m) + '°C';
        document.getElementById('desc').textContent = WMO(code);
        document.getElementById('icon').textContent = ICONS[code] || '🌡️';
        document.getElementById('wind').textContent = cur.wind_speed_10m + ' km/h';
        document.getElementById('code').textContent = code;
        card.hidden = false;
        saveRecent(city);
      })
      .catch(function (e) {
        errorCard.textContent = 'Error: ' + e.message;
        errorCard.hidden = false;
      });
  }

  function WMO(code) {
    var map = {0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Rime fog',51:'Light drizzle',53:'Moderate drizzle',55:'Dense drizzle',61:'Slight rain',63:'Moderate rain',65:'Heavy rain',71:'Slight snow',73:'Moderate snow',75:'Heavy snow',80:'Rain showers',81:'Moderate showers',82:'Violent showers',95:'Thunderstorm',96:'Thunderstorm + hail',99:'Thunderstorm + heavy hail'};
    return map[code] || 'Unknown';
  }

  form.addEventListener('submit', function (e) { e.preventDefault(); search(); });
  renderRecent();
})();
